package com.example;

import com.example.events.EntityDamaged;
import com.example.raids.Cox;
import com.example.raids.Misc;
import com.example.raids.Toa;
import com.example.utils.DamageHandler;
import com.google.inject.Provides;
import javax.inject.Inject;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.party.WSClient;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Raid Death Indicator"
)
public class AkkhaPredictor extends Plugin {
	@Inject
	private AkkhaPredictorOverlay overlay;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private WSClient wsClient;

	@Inject
	private DamageHandler damageHandler;

	@Inject
	private Toa toa;

	@Inject
	private Cox cox;

	@Inject
	private Misc misc;

	@Inject
	private ClientThread clientThread;

	@Inject
	private EventBus eventBus;

	@Override
	protected void startUp() throws Exception
	{
		eventBus.register(damageHandler);
		eventBus.register(toa);
		eventBus.register(cox);
		eventBus.register(misc);
		clientThread.invoke(damageHandler::initXpMap);
		overlayManager.add(overlay);
		wsClient.registerMessage(EntityDamaged.class);
	}
	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		eventBus.unregister(damageHandler);
		eventBus.unregister(toa);
		eventBus.unregister(cox);
		eventBus.unregister(misc);
		wsClient.unregisterMessage(EntityDamaged.class);
		damageHandler.getPredictor().reset();
	}

	@Provides
	AkkhaPredictorConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AkkhaPredictorConfig.class);
	}
}

package com.example;

import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

import java.awt.*;

@ConfigGroup("raid-death-indicator")
public interface AkkhaPredictorConfig extends Config {

    @ConfigSection(
            name = "HP overlay",
            description = "Visual settings for the per-NPC HP overlay text.",
            position = 100,
            closedByDefault = true
    )
    String hpOverlaySection = "hpOverlaySection";

    @ConfigSection(
            name = "Advanced",
            description = "Experimental / debugging toggles. Don't touch unless you know what they do.",
            position = 200,
            closedByDefault = true
    )
    String advancedSection = "advancedSection";

    @Alpha
    @ConfigItem(
            keyName = "highlightColor",
            name = "Highlight color",
            description = ""
    )
    default Color highlightColor() {
        return new Color(98, 174, 253, 64);
    }

    @ConfigItem(
            keyName = "maxHp",
            name = "Max HP",
            description = "Max HP in CoX, affects scales"
    )
    default int maxHp() {
        return 99;
    }

    @ConfigItem(
            keyName = "showStatus",
            name = "Show predictor status",
            description = "Show or hide the box in top left"
    )
    default boolean status() {
        return true;
    }

    @ConfigItem(
            keyName = "isCm",
            name = "Challenge mode",
            description = "To use challenge mode stats or not."
    )
    default boolean isCM() {
        return true;
    }

    // ---------------- HP overlay section ----------------

    @ConfigItem(
            keyName = "enableHpOverlay",
            name = "Enable HP overlay",
            description = "Draws the tracked health on the boss, please use this when reporting bugs",
            section = hpOverlaySection
    )
    default boolean enableHpOverlay() {
        return false;
    }

    @Alpha
    @ConfigItem(
            keyName = "textColor",
            name = "Text color",
            description = "",
            section = hpOverlaySection
    )
    default Color textColor() {
        return new Color(98, 174, 253, 64);
    }

    @ConfigItem(
            keyName = "hpOverlayHeightOffset",
            name = "HP overlay height offset",
            description = "Pixels above the NPC's top edge to draw the HP overlay text. Larger = higher.",
            section = hpOverlaySection
    )
    default int hpOverlayHeightOffset() {
        return 14;
    }

    @ConfigItem(
            keyName = "hpOverlayFontSize",
            name = "HP overlay font size",
            description = "Point size of the HP overlay text.",
            section = hpOverlaySection
    )
    default int hpOverlayFontSize() {
        return 14;
    }

    @ConfigItem(
            keyName = "hpOverlayFormat",
            name = "HP overlay format",
            description = "<html>Tokens:"
                    + "<br>&nbsp;&nbsp;%ch = current HP"
                    + "<br>&nbsp;&nbsp;%qh = queued HP (current minus queued damage)"
                    + "<br>&nbsp;&nbsp;%qd = queued damage"
                    + "<br><br>Wrap a section in %[...] to hide it when a token inside is 0."
                    + "<br>Example: \"%ch%[ (%qd)]\" hides the parens when no damage is queued."
                    + "</html>",
            section = hpOverlaySection
    )
    default String hpOverlayFormat() {
        return "%ch%[ (%qd)]";
    }

    // ---------------- Advanced section ----------------

    @ConfigItem(
            keyName = "conservativeHitPrediction",
            name = "Conservative hit prediction",
            description = "Will not try to use internal fractions until the calibration is done",
            section = advancedSection
    )
    default boolean experimentalHitPrediction() {
        return false;
    }

}

package com.example;

import com.example.enemydata.Enemy;
import com.example.raids.Toa;
import com.example.utils.DamageHandler;
import com.example.utils.Predictor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Point;
import net.runelite.api.Skill;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

import javax.inject.Inject;
import java.awt.*;

@Slf4j
public class AkkhaPredictorOverlay extends Overlay {
    @Inject
    private AkkhaPredictorConfig config;

    @Inject
    private Client client;

    @Inject
    private DamageHandler damageHandler;

    @Inject
    public void initialize() {
        setPosition(OverlayPosition.DYNAMIC);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        var enemies = damageHandler.getActiveEnemies();

        for (Enemy enemy : enemies.values()) {
            NPC npc = enemy.getNpc();
            if (npc == null) {
                continue;
            }
            // Wrap per-enemy so a transitional NPC state (e.g. Akkha during her
            // memory special, where the model is briefly unavailable and the
            // RuneLite NPC APIs throw internally) doesn't take down the rest of
            // the overlay. RuneLite wraps the root NPE in its own exception
            // type, so we widen to Throwable to catch all flavours.
            try {
                if (enemy.shouldHighlight()) {
                    renderPoly(graphics, null, 0, config.highlightColor(), npc.getConvexHull());
                }
                if (config.enableHpOverlay()) {
                    int hp = enemy.getCurrentHealth();
                    int queued = enemy.getQueuedDamage();
                    String full = formatHp(config.hpOverlayFormat(), hp, queued);
                    // The "anchor" is the format with all %[...] blocks
                    // unconditionally stripped. We position the text based on
                    // this stable string's width so the always-present prefix
                    // (e.g. "%ch") never moves when a conditional block
                    // appears/disappears — extra content just extends to the
                    // right.
                    String anchorText = formatHpStripped(config.hpOverlayFormat(), hp, queued);
                    renderText(graphics, npc, full, anchorText, config.textColor());
                }
            } catch (Throwable ignored) {
                // NPC is in a half-spawned state; nothing meaningful to draw this frame.
            }
        }

        if (!Toa.isAtToa(client) || !config.status()) {
            return null;
        }

        Skill[] skills = new Skill[] { Skill.HITPOINTS };
        int start = 20;
        Predictor predictor = damageHandler.getPredictor();

        for (Skill skill : skills) {
            if (predictor.isAccurate(skill)) {
                graphics.setColor(Color.green);
                graphics.fillRect(10, start, 10, 10);
            } else if (predictor.isDead(skill)) {
                graphics.setColor(Color.pink);
                graphics.fillRect(10, start, 10, 10);
            } else {
                graphics.setColor(Color.red);
                graphics.fillRect(10, start, 10, 10);
            }
            start += 20;
        }
        return null;
    }

    /**
     * Substitute %ch / %qh / %qd into the user's overlay format string.
     * %ch = current HP, %qh = current minus queued damage, %qd = queued damage.
     *
     * <p>Supports a bracketed conditional: {@code %[...]} blocks are stripped
     * if any numeric token inside them would resolve to 0. So a format of
     * {@code "%ch%[ (%qd)]"} renders as {@code "550 (50)"} when there's queued
     * damage and just {@code "550"} when there isn't.</p>
     */
    static String formatHp(String format, int currentHp, int queuedDamage) {
        int qh = currentHp - queuedDamage;
        StringBuilder out = new StringBuilder(format.length());
        int i = 0;
        while (i < format.length()) {
            if (i + 1 < format.length() && format.charAt(i) == '%' && format.charAt(i + 1) == '[') {
                int close = format.indexOf(']', i + 2);
                if (close < 0) {
                    out.append(format, i, format.length());
                    break;
                }
                String block = format.substring(i + 2, close);
                if (!blockHasZeroToken(block, currentHp, qh, queuedDamage)) {
                    out.append(substituteTokens(block, currentHp, qh, queuedDamage));
                }
                i = close + 1;
            } else {
                out.append(format.charAt(i));
                i++;
            }
        }
        return substituteTokens(out.toString(), currentHp, qh, queuedDamage);
    }

    /**
     * Same token substitution as {@link #formatHp} but always strips every
     * {@code %[...]} block. Used as the positioning anchor: text is rendered
     * starting at the X that would centre this stripped string, so the parts
     * of the format that are *always* present stay pinned in place when a
     * conditional block toggles on or off.
     */
    static String formatHpStripped(String format, int currentHp, int queuedDamage) {
        int qh = currentHp - queuedDamage;
        StringBuilder out = new StringBuilder(format.length());
        int i = 0;
        while (i < format.length()) {
            if (i + 1 < format.length() && format.charAt(i) == '%' && format.charAt(i + 1) == '[') {
                int close = format.indexOf(']', i + 2);
                if (close < 0) {
                    out.append(format, i, format.length());
                    break;
                }
                i = close + 1; // skip block entirely
            } else {
                out.append(format.charAt(i));
                i++;
            }
        }
        return substituteTokens(out.toString(), currentHp, qh, queuedDamage);
    }

    private static boolean blockHasZeroToken(String block, int ch, int qh, int qd) {
        if (block.contains("%ch") && ch == 0) return true;
        if (block.contains("%qh") && qh == 0) return true;
        if (block.contains("%qd") && qd == 0) return true;
        return false;
    }

    private static String substituteTokens(String s, int ch, int qh, int qd) {
        return s
                .replace("%ch", Integer.toString(ch))
                .replace("%qh", Integer.toString(qh))
                .replace("%qd", Integer.toString(qd));
    }

    private void renderText(Graphics2D graphics, NPC npc, String drawText, String anchorText, Color c) {
        if (npc == null) {
            return;
        }
        graphics.setFont(FontManager.getRunescapeBoldFont().deriveFont((float) config.hpOverlayFontSize()));
        // Tile-based anchor — projected from the NPC's LocalPoint + logical
        // height. Stays still through animation, and the anchorText (= the
        // user's format with all %[...] blocks stripped) keeps the always-on
        // prefix pinned in place: conditional content just extends to the
        // right when it toggles on.
        Point anchor = npc.getCanvasTextLocation(graphics, anchorText, npc.getLogicalHeight());
        if (anchor == null) {
            return;
        }
        int y = anchor.getY() - config.hpOverlayHeightOffset();
        OverlayUtil.renderTextLocation(graphics, new Point(anchor.getX(), y), drawText, c);
    }

    private void renderPoly(Graphics2D graphics, Color borderColor, float borderWidth, Color fillColor, Shape polygon) {
        if (polygon != null) {
            graphics.setColor(borderColor);
            graphics.setStroke(new BasicStroke(borderWidth));
            graphics.draw(polygon);
            graphics.setColor(fillColor);
            graphics.fill(polygon);
        }
    }
}

package com.example.enemydata;

import lombok.Getter;
import lombok.Setter;
import lombok.Synchronized;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.gameval.NpcID;

import java.util.HashSet;
import java.util.Set;

@Slf4j
public abstract class Enemy implements IEnemy {
    public static final Set<Integer> blacklist = Set.of(NpcID.TOA_KEPHRI_SHIELD_SCARAB, NpcID.TOA_ZEBAK_JUG, NpcID.TOA_ZEBAK_JUG_ROLLING);
    public static final Set<Integer> bosses;

    @Getter(onMethod_ = { @Synchronized })
    @Setter(onMethod_ = { @Synchronized })
    public int queuedDamage;
    public boolean shouldDraw;
    @Getter(onMethod_ = { @Synchronized })
    protected boolean hideOnDeath;

    public final int baseHealth;
    // TODO: this may require some rework, akkha for example computes the xp modifier before rounding hp
    @Getter(onMethod_ = { @Synchronized })
    public int scaledHealth;
    @Getter(onMethod_ = { @Synchronized })
    public int currentHealth;

    protected int attack;
    protected int str;
    protected int def;
    protected int offAtt;
    protected int offStr;
    protected int defStab;
    protected int defSlash;
    protected int defCrush;

    /**
     * Damage multiplier for a given enemy. Examples for these are {@link} NightmareTotem
     * and Ice Demon (TODO).
     *
     * Defaults to 1.
     */
    @Getter
    protected int damageMultiplier;

    /**
     * How often a mob regens health (in ticks).
     */
    @Getter
    protected int regenCycle;

    @Getter
    @Setter
    NPC npc;

    @Setter
    @Getter
    Client client;

    static {
        bosses = new HashSet<>();
        // Add the NpcID values to the Set
        bosses.add(NpcID.AKKHA_SPAWN);
        bosses.add(NpcID.AKKHA_MELEE);
        bosses.add(NpcID.AKKHA_RANGE);
        bosses.add(NpcID.AKKHA_MAGE);
        bosses.add(NpcID.AKKHA_ENRAGE_SPAWN);
        bosses.add(NpcID.AKKHA_ENRAGE_INITIAL);
        bosses.add(NpcID.AKKHA_ENRAGE);
        bosses.add(NpcID.AKKHA_ENRAGE_DUMMY);

        bosses.add(NpcID.TOA_BABA);
        bosses.add(NpcID.TOA_BABA_COFFIN);
        bosses.add(NpcID.TOA_BABA_DIGGING);

        bosses.add(NpcID.TOA_KEPHRI_BOSS_SHIELDED);
        bosses.add(NpcID.TOA_KEPHRI_BOSS_ENRAGE);

        bosses.add(NpcID.TOA_ZEBAK);
        bosses.add(NpcID.TOA_ZEBAK_ENRAGED);

        bosses.add(NpcID.TOA_WARDENS_P1_OBELISK_NPC);
        bosses.add(NpcID.TOA_WARDEN_ELIDINIS_PHASE2_MAGE);
        bosses.add(NpcID.TOA_WARDEN_ELIDINIS_PHASE2_RANGE);
        bosses.add(NpcID.TOA_WARDEN_ELIDINIS_PHASE3);
        bosses.add(NpcID.TOA_WARDEN_TUMEKEN_PHASE2_MAGE);
        bosses.add(NpcID.TOA_WARDEN_TUMEKEN_PHASE2_RANGE);
        bosses.add(NpcID.TOA_WARDEN_TUMEKEN_PHASE3);

        bosses.add(NpcID.RAIDS_VESPULA_PORTAL);
        bosses.add(NpcID.RAIDS_VASANISTIRIO_WALKING);
        bosses.add(NpcID.RAIDS_VANGUARD_RANGED);
        bosses.add(NpcID.RAIDS_VANGUARD_MAGIC);
        bosses.add(NpcID.RAIDS_VANGUARD_MELEE);
        bosses.add(NpcID.OLM_HAND_RIGHT);
    }

    protected Enemy(NPC npc, int baseHealth, int attack, int str, int def,
            int offAtt, int offStr,
            int defStab, int defSlash, int defCrush) {
        this.npc = npc;

        this.baseHealth = baseHealth;
        // Set sane default for scaled health
        this.scaledHealth = baseHealth;
        this.currentHealth = baseHealth;
        this.attack = attack;
        this.str = str;
        this.def = def;
        this.offAtt = offAtt;
        this.offStr = offStr;
        this.defStab = defStab;
        this.defSlash = defSlash;
        this.defCrush = defCrush;
        this.shouldDraw = false;
        this.hideOnDeath = false;
        this.queuedDamage = 0;
        this.damageMultiplier = 1;
        this.regenCycle = 0;
    }

    public synchronized void setCurrentHealth(int hp) {
        if (hp >= 0) {
            currentHealth = hp;
        }
    }

    public synchronized int hit(int damage) {
        queuedDamage = Math.max(0, queuedDamage - damage);
        currentHealth -= damage;
        if (queuedDamage == 0) {
            // Queued prediction has been fully consumed by landed hitsplats.
            // shouldDraw was set when the prediction was made; clear it now that
            // the predicted event has resolved.
            shouldDraw = false;
        }
        return currentHealth;
    }

    public synchronized int heal(int amount) {
        // Cap at scaledHealth — RuneLite reports the full requested heal value
        // on hitsplats (e.g. Vanguards' group-heal mechanic), but the game
        // itself never exceeds max HP. Without this clamp, a Vanguard at 104
        // hp receiving a HEAL 114 ends up at 218 (max is 180).
        currentHealth = Math.min(currentHealth + amount, scaledHealth);
        // Heals (including phase-transition heals like Akkha's) invalidate any
        // standing prediction.
        shouldDraw = false;
        return currentHealth;
    }

    /**
     * Queues damage and counts if the enemy will die to it.
     *
     * <p>
     * Pure state mutation — the caller is responsible for any client-thread
     * side effects (e.g. {@code npc.setDead(...)}) based on the returned value,
     * since this method can be invoked from the network thread.
     * </p>
     *
     * @param damage damage dealt.
     * @return true if the mob died, false if not.
     */
    public synchronized boolean queueDamage(int damage) {
        queuedDamage += damage;
        shouldDraw = queuedDamage >= currentHealth;
        return shouldDraw;
    }

    public synchronized boolean shouldHighlight() {
        return shouldDraw;
    }

    public double getModifier() {
        return computeModifier(getAvgDef(), offStr, offAtt);
    }

    /**
     * Modifier formula with overridable offensive bonuses (defensive bonuses
     * default to the standard {@code (stab+slash+crush)/3} average).
     */
    protected double computeModifier(int offStrength, int offAttack) {
        return computeModifier(getAvgDef(), offStrength, offAttack);
    }

    /**
     * Modifier formula with all variable inputs explicit — for subclasses whose
     * defensive bonuses ALSO depend on runtime state (e.g. Vanguards have
     * completely different stab/slash/crush per combat style).
     */
    protected double computeModifier(int avgDef, int offStrength, int offAttack) {
        double avgs = Math.floor((getAvgLevel() * (avgDef + offStrength + offAttack)) / 5120d);
        avgs /= 40d;
        return Math.max(1.0d, 1 + avgs);
    }

    private int getAvgLevel() {
        return (attack + str + def + Math.min(getScaledHealth(), 2000)) / 4;
    }

    private int getAvgDef() {
        return (defStab + defSlash + defCrush) / 3;
    }
}

package com.example.enemydata;

public interface IEnemy {
    int hit(int damage);
}

package com.example.enemydata.cox;

import com.example.enemydata.Enemy;
import com.example.utils.HexFunction;

import lombok.Getter;
import lombok.Setter;
import lombok.Synchronized;
import net.runelite.api.NPC;
import net.runelite.api.gameval.NpcID;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class CoxEnemy extends Enemy {
    public static final Map<Integer, HexFunction<NPC, Boolean, Integer, Integer, Integer, Long, CoxEnemy>> enemies;
    boolean isCm;
    int partySize;
    int maxHp;

    @Getter(onMethod_ = { @Synchronized })
    @Setter(onMethod_ = { @Synchronized })
    boolean stalled;

    @Getter(onMethod_ = { @Synchronized })
    @Setter(onMethod_ = { @Synchronized })
    long raidTick;

    static {
        enemies = new HashMap<>();

        enemies.put(NpcID.RAIDS_VESPULA_PORTAL, Portal::new);
        enemies.put(NpcID.RAIDS_SKELETONMYSTIC_A, SkeletalMystic::new);
        enemies.put(NpcID.RAIDS_SKELETONMYSTIC_B, SkeletalMystic::new);
        enemies.put(NpcID.RAIDS_SKELETONMYSTIC_C, SkeletalMystic::new);
        enemies.put(NpcID.RAIDS_LIZARDSHAMAN_A, LizardmanShaman::new);
        enemies.put(NpcID.RAIDS_LIZARDSHAMAN_B, LizardmanShaman::new);
        enemies.put(NpcID.RAIDS_VASANISTIRIO_DORMANT, VasaNistirio::new);
        enemies.put(NpcID.OLM_HAND_RIGHT_SPAWNING, OlmMageHand::new);
        enemies.put(NpcID.OLM_HAND_RIGHT, OlmMageHand::new);
        enemies.put(NpcID.RAIDS_VANGUARD_DORMANT, Vanguard::new);
        enemies.put(NpcID.RAIDS_VANGUARD_WALKING, Vanguard::new);
        enemies.put(NpcID.RAIDS_VANGUARD_MELEE, Vanguard::new);
        enemies.put(NpcID.RAIDS_VANGUARD_RANGED, Vanguard::new);
        enemies.put(NpcID.RAIDS_VANGUARD_MAGIC, Vanguard::new);

        // Disabled for now, until a way to calculate the average mining level
        // for a raid is figured out. Guardians will also likely never work
        // properly unless everyone is in party. That or some other cursed
        // shenanigans.
        enemies.put(NpcID.RAIDS_STONEGUARDIANS_LEFT, Guardian::new);
        enemies.put(NpcID.RAIDS_STONEGUARDIANS_RIGHT, Guardian::new);

        enemies.put(NpcID.RAIDS_DOGODILE_SUBMERGED, GreatMuttadile::new);
        enemies.put(NpcID.RAIDS_DOGODILE, GreatMuttadile::new);
        enemies.put(NpcID.RAIDS_DOGODILE_JUNIOR, SmallMuttadile::new);
    }

    protected CoxEnemy(NPC npc, boolean isCm, int partySize,
            int maxCombat, int maxHp, long raidTick,
            int baseHealth, int melee, int def, int offAtt, int offStr,
            int defStab, int defSlash, int defCrush) {

        super(npc, baseHealth, melee, melee, def, offAtt, offStr, defStab, defSlash, defCrush);
        assert (attack == str);
        this.isCm = isCm;
        this.partySize = partySize;
        this.maxHp = maxHp;
        this.stalled = false;
        this.raidTick = raidTick;

        this.scaledHealth = this.getScaledHealth(baseHealth, maxCombat, partySize);
        this.currentHealth = scaledHealth;
        int scaledDef = getScaledDefence(def, partySize, maxHp);
        this.def = scaledDef;
        int scaledMelee = getScaledOffence(melee, partySize, maxHp);
        this.str = scaledMelee;
        this.attack = scaledMelee;
        //this.regenCycle = 100;
    }

    // CoX scaling — ported from the OSRS DPS calculator's applyMultiCoxScaling.
    // https://github.com/weirdgloop/osrs-dps-calc / src/lib/scaling/CoxMonsterScaling.ts
    //
    // Inputs clamp:
    //   highestComLevel ∈ [60, 126]
    //   highestHp       ∈ [55, 99]   (curve: 55 + 44·maxHp/99)
    //   partySize       ∈ [1, 100]
    //
    // Outputs clamp (sanity from the calculator):
    //   hp        ∈ [50,   30_000]
    //   offensive ∈ [50,    5_000]
    //   defensive ∈ [50,   20_000]
    //
    // CM is a flat +50% on everything we currently track (Tekton + glowing
    // crystal special cases from the calculator are not modelled — we don't
    // track those NPCs).
    private static final int HP_CLAMP_LO = 50, HP_CLAMP_HI = 30_000;
    private static final int OFFENCE_CLAMP_LO = 50, OFFENCE_CLAMP_HI = 5_000;
    private static final int DEFENCE_CLAMP_LO = 50, DEFENCE_CLAMP_HI = 20_000;

    /**
     * Increments the current raid tick for an NPC, handles regen cycles and
     * stalls.
     */
    public void incrementRaidTick() {
        if (isStalled()) {
            // If NPC is stalled we shouldn't do anything, NPC queues are
            // paused for the duration of a stall.
            return;
        }

        if (regenCycle > 0 && (raidTick % regenCycle) == 0) {
            heal(1);
        }

        if (raidTick == Long.MAX_VALUE) {
            raidTick = 0;
        } else {
            raidTick++;
        }
    }

    private static int clampPartySize(int partySize) {
        return Math.max(1, Math.min(100, partySize));
    }

    private static int highestComLevel(int maxCombat) {
        return Math.max(60, Math.min(126, maxCombat));
    }

    private static int highestHp(int maxHp) {
        // 55 + ⌊44·maxHp / 99⌋, then clamped to [55, 99].
        int v = 55 + 44 * maxHp / 99;
        return Math.max(55, Math.min(99, v));
    }

    protected int getScaledDefence(int baseDef, int partySize, int maxHp) {
        int hh = highestHp(maxHp);
        int psm1 = clampPartySize(partySize) - 1;
        int defensive = baseDef * hh / 99;
        int scalePct = 100 + (int) Math.sqrt(psm1) + psm1 * 7 / 10;
        defensive = defensive * scalePct / 100;
        if (isCm) {
            defensive = defensive * 3 / 2;
        }
        return Math.max(DEFENCE_CLAMP_LO, Math.min(DEFENCE_CLAMP_HI, defensive));
    }

    protected int getScaledOffence(int baseStat, int partySize, int maxHp) {
        int hh = highestHp(maxHp);
        int psm1 = clampPartySize(partySize) - 1;
        int offensive = baseStat * hh / 99;
        int scalePct = 100 + (int) Math.sqrt(psm1) * 7 + psm1;
        offensive = offensive * scalePct / 100;
        if (isCm) {
            offensive = offensive * 3 / 2;
        }
        return Math.max(OFFENCE_CLAMP_LO, Math.min(OFFENCE_CLAMP_HI, offensive));
    }

    // TODO: override for olm
    protected int getScaledHealth(int baseHp, int maxCombat, int partySize) {
        int hcl = highestComLevel(maxCombat);
        int ps = clampPartySize(partySize);
        int hp = baseHp * hcl / 126;
        // hp *= 1 + ⌊partySize/2⌋  (since ⌊partySize·50/100⌋ = ⌊partySize/2⌋)
        hp += hp * (ps * 50 / 100);
        if (isCm) {
            hp = hp * 3 / 2;
        }
        return Math.max(HP_CLAMP_LO, Math.min(HP_CLAMP_HI, hp));
    }
}

