package com.example.raids;

import net.runelite.api.gameval.*;
import net.runelite.api.gameval.NpcID;

import com.example.AkkhaPredictorConfig;
import com.example.enemydata.*;
import com.example.enemydata.cox.CoxEnemy;
import com.example.utils.DamageHandler;
import lombok.Getter;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.hiscore.HiscoreClient;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.atomic.AtomicBoolean;

@Singleton
public class Cox {
    @Inject
    private DamageHandler damageHandler;

    @Inject
    private Client client;

    @Inject
    private HiscoreClient hiscoreClient;

    @Inject
    private AkkhaPredictorConfig config;

    @Getter
    AtomicBoolean cachedInCox;

    boolean isCm;

    int groupSize;

    int maxCombat;

    int maxHp;

    /**
     * Ticks since raid started, used to account for regen.
     */
    long raidTick;

    @Inject
    public void initialize() {
        cachedInCox = new AtomicBoolean();
        cachedInCox.set(false);
        isCm = false;
        groupSize = 0;
        maxCombat = 0;
        maxHp = 0;
    }

    public static boolean isInCox(Client client) {
        int state = client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON);
        return state == 1;
    }

    public boolean isInCox() {
        return isInCox(client);
    }

    @Subscribe
    public void onGameTick(GameTick ev) {
        if (!isInCox()) {
            return;
        }

        for (Enemy e : damageHandler.getActiveEnemies().values()) {
            if (e instanceof CoxEnemy) {
                CoxEnemy coxEnemy = (CoxEnemy) e;
                coxEnemy.incrementRaidTick();
            }
        }

        if (raidTick == Long.MAX_VALUE) {
            raidTick = 0;
        } else {
            raidTick++;
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged ev) {
        switch (ev.getVarbitId()) {
            case VarbitID.RAIDS_CLIENT_PROGRESS:
                if (ev.getValue() == 1) {
                    boolean isLeader = client.getVarbitValue(VarbitID.RAIDS_CLIENT_ISLEADER) != 0;
                    isCm = isLeader
                            ? client.getVarbitValue(VarbitID.RAIDS_CHALLENGE_MODE) != 0
                            : config.isCM();
                    groupSize = client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSIZE_SCALED);
                    maxHp = config.maxHp();
                    maxCombat = client.getServerVarbitValue(VarbitID.RAIDS_CLIENT_HIGHESTCOMBAT);
                    raidTick = 0;
                }
                cachedInCox.set(ev.getValue() >= 1 && ev.getValue() < 5);
                break;
            case VarbitID.RAIDS_CLIENT_INDUNGEON:
                if (ev.getValue() == 0) {
                    damageHandler.getActiveEnemies().clear();
                }
                break;

        }
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned ev) {
        if (!isInCox()) {
            return;
        }
        NPC npc = ev.getNpc();
        var activeEnemies = damageHandler.getActiveEnemies();
        activeEnemies.remove(npc.getIndex());
    }

    @Subscribe
    public void onNpcSpawned(NpcSpawned ev) {
        if (!isInCox()) {
            return;
        }
        trackIfTrackable(ev.getNpc());
    }

    /**
     * Some COX NPCs (e.g. Vanguards) spawn under one id and transition to a
     * different id via NpcChanged. If only the post-change id is in our
     * registry, the spawn handler would miss them — handle the change too.
     */
    @Subscribe
    public void onNpcChanged(NpcChanged ev) {
        if (!isInCox()) {
            return;
        }
        NPC npc = ev.getNpc();
        trackIfTrackable(npc);

        var activeEnemies = damageHandler.getActiveEnemies();
        CoxEnemy enemy;

        switch (npc.getId()) {
            case NpcID.RAIDS_STONEGUARDIANS_RIGHT_DEAD:
            case NpcID.RAIDS_STONEGUARDIANS_LEFT_DEAD:
                activeEnemies.remove(npc.getIndex());
                break;

            case NpcID.RAIDS_VANGUARD_WALKING:
                enemy = (CoxEnemy) activeEnemies.get(npc.getIndex());
                enemy.heal(1);
                enemy.setStalled(true);
                break;

            case NpcID.RAIDS_VANGUARD_RANGED:
            case NpcID.RAIDS_VANGUARD_MAGIC:
            case NpcID.RAIDS_VANGUARD_MELEE:
                enemy = (CoxEnemy) activeEnemies.get(npc.getIndex());
                enemy.setStalled(false);
                break;
        }
    }

    private void trackIfTrackable(NPC npc) {
        var activeEnemies = damageHandler.getActiveEnemies();
        if (activeEnemies.containsKey(npc.getIndex())) {
            // Already tracking this NPC index — id change at the same index is
            // typically a state transition (e.g. Vanguard sleep → combat), the
            // existing Enemy keeps the live npc reference.
            return;
        }

        var enemyConstructor = CoxEnemy.enemies.getOrDefault(npc.getId(), null);
        if (enemyConstructor == null) {
            return;
        }

        // TODO: Add support for guardians in non-solo
        if ((npc.getId() == NpcID.RAIDS_STONEGUARDIANS_RIGHT ||
                npc.getId() == NpcID.RAIDS_STONEGUARDIANS_LEFT) && groupSize != 1) {
            return;
        }

        Enemy enemy = enemyConstructor.apply(npc, isCm, groupSize, maxCombat, maxHp, raidTick);
        activeEnemies.put(npc.getIndex(), enemy);
    }
}

package com.example.raids;

import com.example.enemydata.Enemy;
import com.example.enemydata.misc.nightmare.NightmareHuskRanged;
import com.example.enemydata.misc.nightmare.NightmareParasite;
import com.example.enemydata.misc.nightmare.NightmareParasiteEnraged;
import com.example.enemydata.misc.nightmare.NightmareHuskMage;
import com.example.enemydata.misc.AbyssalSire;
import com.example.enemydata.misc.nightmare.NightmareTotem;
import com.example.enemydata.misc.nightmare.PhosaniParasite;
import com.example.enemydata.misc.nightmare.PhosaniParasiteEnraged;
import com.example.utils.DamageHandler;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.events.NpcChanged;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Handler for "miscellaneous" tracked bosses that don't fit under anything
 * really.
 */
@Singleton
@Slf4j
public class Misc {
    @Inject
    private Client client;

    @Inject
    private DamageHandler damageHandler;

    @Subscribe
    protected void onNpcSpawned(NpcSpawned event) {
        NPC npc = event.getNpc();
        var activeEnemies = damageHandler.getActiveEnemies();
        int idx = npc.getIndex();

        if (NightmareTotem.NPC_IDS.contains(npc.getId())) {
            activeEnemies.put(idx, new NightmareTotem(npc, client));
        } else {
            switch (npc.getId()) {
                case NpcID.NIGHTMARE_HUSK_MAGIC:
                    activeEnemies.put(idx, new NightmareHuskMage(npc));
                    break;

                case NpcID.NIGHTMARE_HUSK_RANGED:
                    activeEnemies.put(idx, new NightmareHuskRanged(npc));
                    break;

                case NpcID.NIGHTMARE_PARASITE_WEAK:
                    if (client.getVarbitValue(VarbitID.PLAYER_IS_IN_NIGHTMARE_CHALLENGE) != 0) {
                        activeEnemies.put(idx, new PhosaniParasite(npc));
                    } else {
                        activeEnemies.put(idx, new NightmareParasite(npc));
                    }
                    break;

                case NpcID.NIGHTMARE_PARASITE:
                    if (client.getVarbitValue(VarbitID.PLAYER_IS_IN_NIGHTMARE_CHALLENGE) != 0) {
                        activeEnemies.put(idx, new PhosaniParasiteEnraged(npc));
                    } else {
                        activeEnemies.put(idx, new NightmareParasiteEnraged(npc));
                    }
                    break;

                // Abyssal Sire — phase 1 (spawn, sleeping / awake / stunned)
                case NpcID.ABYSSALSIRE_SIRE_STASIS_SLEEPING:
                case NpcID.ABYSSALSIRE_SIRE_STASIS_AWAKE:
                case NpcID.ABYSSALSIRE_SIRE_STASIS_STUNNED:
                    activeEnemies.putIfAbsent(idx, new AbyssalSire(npc));
                    break;
            }
        }
    }

    @Subscribe
    protected void onNpcChanged(NpcChanged event) {
        var activeEnemies = damageHandler.getActiveEnemies();
        NPC npc = event.getNpc();
        int idx = npc.getIndex();
        int id = npc.getId();

        if (NightmareTotem.NPC_IDS.contains(id)) {
            activeEnemies.replace(idx, new NightmareTotem(npc, client));
        }

        // Abyssal Sire — phase transitions
        switch (id) {
            // Phase 2: throne (puppet / wandering)
            case NpcID.ABYSSALSIRE_SIRE_PUPPET:
            case NpcID.ABYSSALSIRE_SIRE_WANDERING:
            case NpcID.ABYSSALSIRE_SIRE_PANICKING:
                // Phase 3 stage 1: off the throne (panicking)
            case NpcID.ABYSSALSIRE_SIRE_APOCALYPSE:
                // Phase 3 stage 2: enrage (apocalypse)
                activeEnemies.putIfAbsent(idx, new AbyssalSire(npc));
                break;
        }
    }

    @Subscribe
    protected void onNpcDespawned(NpcDespawned event) {
        NPC npc = event.getNpc();
        // Remove value if it exists
        damageHandler.getActiveEnemies().remove(npc.getIndex());
    }
}

package com.example.raids;

import com.example.enemydata.Enemy;
import com.example.enemydata.toa.ToaEnemy;
import com.example.enemydata.toa.het.Akkha;
import com.example.enemydata.toa.het.AkkhaShadow;
import com.example.utils.DamageHandler;
import com.example.utils.QuadFunction;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.events.*;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Arrays;

@Singleton
@Slf4j
public class Toa {
    @Inject
    private Client client;

    @Inject
    private DamageHandler damageHandler;

    public static boolean isAtToa(Client client) {
        final int[] TOA_REGIONS = {
                13455, // Lobby
                14160, // Nexus

                15698, // Crondis
                15700, // Zebak

                14162, // Scabaras
                14164, // Kephri

                15186, // Apmken
                15188, // Baba

                14674, // Het
                14676, // Akkha

                // 15184, // Wardens
                // 15696, // Wardens

                // 14672, // Tomb
        };

        return Arrays.stream(client.getTopLevelWorldView().getMapRegions())
                .anyMatch(current -> Arrays.stream(TOA_REGIONS).anyMatch(reg -> reg == current));
    }

    public boolean isAtToa() {
        return isAtToa(client);
    }

    /**
     * @return TOA invocation level
     */
    private int getInvocation() {
        return client.getVarbitValue(VarbitID.TOA_CLIENT_RAID_LEVEL);
    }

    /**
     * Fetches the path level from the TOA widget
     *
     * @return Path level
     */
    private int getPathLevel() {
        Widget pathLevelWidget = client.getWidget(481, 45);
        if (pathLevelWidget == null) {
            return -1;
        }
        return Integer.parseInt(pathLevelWidget.getText());
    }

    /**
     * Gets amount of people in the raid, amount makes the enemy health scale with 90%
     *
     * @return Amount of people in the raid
     */
    private int getPartySize() {
        int partySize = 1;
        for (int i = 1; i < 8; i++) {
            if (client.getVarbitValue(VarbitID.TOA_CLIENT_P0 + i) != 0) {
                partySize++;
            }
        }
        return partySize;
    }

    private boolean partyDead() {

        for (int i = VarbitID.TOA_CLIENT_P0; i <= VarbitID.TOA_CLIENT_P7; i++) {
            int value = client.getVarbitValue(i);
            if (value != 30 && value != 0) {
                return false;
            }
        }

        return true;
    }

    /**
     * Create the new Akkha object when the TOA path widget has loaded, we aren't able to get the path level otherwise.
     *
     * @param event
     */
    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event) {
        // 481 is the TOA path/time/etc. widget
        if (event.getGroupId() != InterfaceID.TOA_HUD) {
            return;
        }
        int invo = getInvocation();
        int pathLevel = getPathLevel();
        int partySize = getPartySize();
        if (pathLevel < 0 || invo < 0 || partySize <= 0) {
            return;
        }
        for (Enemy enemy : damageHandler.getActiveEnemies().values()) {
            if (enemy instanceof ToaEnemy) {
                ToaEnemy e = (ToaEnemy) enemy;
                e.fixupStats(invo, partySize, pathLevel);
            }
        }
    }

    @Subscribe
    protected void onNpcDespawned(NpcDespawned event) {
        if (!isAtToa()) {
            return; // only handle toa enemies
        }
        NPC npc = event.getNpc();
        boolean isAkkha = Akkha.isAkkha(npc.getId());
        boolean isPartyDead = partyDead();
        if (isAkkha && !isPartyDead) {
            return;
        }
        var activeEnemies = damageHandler.getActiveEnemies();
        Enemy despawning = activeEnemies.get(npc.getIndex());
        if (despawning instanceof AkkhaShadow) {
            activeEnemies.values().stream()
                    .filter(e -> e instanceof Akkha)
                    .forEach(e -> e.setQueuedDamage(0));
        }
        activeEnemies.remove(npc.getIndex());
    }

    @Subscribe
    protected void onNpcSpawned(NpcSpawned event) {
        if (!isAtToa()) {
            return;
        }
        var activeEnemies = damageHandler.getActiveEnemies();
        NPC npc = event.getNpc();
        if (activeEnemies.containsKey(npc.getIndex())) {
            Enemy enemy = activeEnemies.get(npc.getIndex());
            enemy.setNpc(npc);
            // Re-sync the health of the enemy (akkha) when it re-appears in case of hits during invuln
            // TODO should akkha be subscribed to the event bus?
            int newHealth = client.getVarbitValue(VarbitID.HPBAR_HUD_HP);
            enemy.setCurrentHealth(newHealth);
            enemy.setQueuedDamage(0);

            return;
        }

        QuadFunction<NPC, Integer, Integer, Integer, Enemy> constructor = ToaEnemy.enemies.getOrDefault(npc.getId(), null);
        if (constructor == null) {
            return;
        }

        Enemy enemy = constructor.apply(npc, getInvocation(), getPartySize(), getPathLevel());
        enemy.setClient(client);

        activeEnemies.put(npc.getIndex(), enemy);
    }
}

package com.example.utils;

import com.example.AkkhaPredictorConfig;
import com.example.enemydata.Enemy;
import com.example.events.EntityDamaged;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.kit.KitType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.stream.Collectors;

/**
 * Damage handler manages the damaging of enemies, the raid classes places and removes enemies from here.
 */
@Singleton
@Slf4j
public class DamageHandler {
    @Getter
    private final ConcurrentMap<Integer, Enemy> activeEnemies = new ConcurrentHashMap<>();

    @Getter
    private final Predictor predictor = new Predictor();

    @Inject
    private Client client;

    @Inject
    ClientThread clientThread;

    @Inject
    private PartyService party;

    @Inject
    private AkkhaPredictorConfig config;
    /**
     * Map of current XP amounts in each skill
     */
    private Map<Skill, Integer> previousXps;

    private final Set<Skill> validSkills = Set.of(Skill.HITPOINTS);

    private static final Set<Integer> POWERED_STAVES = new HashSet<>(Arrays.asList(
            ItemID.TOTS_CHARGED, // Trident of the seas (full)
            ItemID.TOTS, // Trident of the seas
            ItemID.TOXIC_TOTS_CHARGED, // Toxic trident of the swamp
            ItemID.TOXIC_TOTS_I_CHARGED,
            ItemID.SANGUINESTI_STAFF,
            ItemID.SANGUINESTI_STAFF_OR,
            ItemID.TUMEKENS_SHADOW,
            ItemID.DEADMAN_BLIGHTED_TUMEKENS_SHADOW,
            ItemID.VOIDWAKER));
    private static final Set<Integer> CHINCHOMPAS = Set.of(
            ItemID.CHINCHOMPA_CAPTURED, // Grey chinchompa
            ItemID.CHINCHOMPA_BLACK, // Black chin
            ItemID.CHINCHOMPA_BIG_CAPTURED // Red chinchompa
    );

    // Multi-target multi-hit weapons. XP drop is the sum across all hit
    // NPCs, so we cannot attribute it to a single target — route through
    // handleAoe (same pattern as chinchompa AoE) for clump-kill prediction.
    // Single-target multi-hits (claws, dagger, etc.) don't need special
    // handling: precise(D1)+precise(D2)+precise(D3) = precise(sum) thanks
    // to linearity, so treePredict on the summed XP returns the total
    // damage and the carry tracks correctly.
    private static final Set<Integer> SCYTHES = Set.of(
            ItemID.SCYTHE_OF_VITUR,
            ItemID.SCYTHE_OF_VITUR_OR,
            ItemID.SCYTHE_OF_VITUR_BL,
            ItemID.SCYTHE_OF_VITUR_UNCHARGED,
            ItemID.SCYTHE_OF_VITUR_UNCHARGED_OR,
            ItemID.SCYTHE_OF_VITUR_UNCHARGED_BL);

    private static final Set<Integer> MULTI_HIT_WEAPONS = Set.of(
            ItemID.DINHS_BULWARK,
            ItemID.DINHS_BULWARK_ORNAMENT,
            ItemID.DRAGON_2H_SWORD,

            ItemID.DRAGON_CLAWS,
            // Burning claws
            ItemID.BONE_CLAWS,
            ItemID.DRAGON_DAGGER,
            ItemID.DRAGON_DAGGER_P,
            ItemID.DRAGON_DAGGER_P_,
            ItemID.DRAGON_DAGGER_P__,
            // Tonalztics of ralos (2-hit standard attack)
            ItemID.TONALZTICS_OF_RALOS_CHARGED,
            ItemID.DRAGON_KNIFE,
            ItemID.DRAGON_KNIFE_P,
            ItemID.DRAGON_KNIFE_P_,
            ItemID.DRAGON_KNIFE_P__);

    public void initXpMap() {
        previousXps = new HashMap<>();
        Arrays.stream(Skill.values()).forEach(skill -> previousXps.put(skill, client.getSkillExperience(skill)));
    }

    @Subscribe
    protected void onGameStateChanged(GameStateChanged gamestate) {
        if (gamestate == null) {
            return;
        }
        GameState state = Objects.requireNonNull(gamestate.getGameState());
        switch (state) {
            case LOGGED_IN:
                initXpMap();
                break;
            default:
                break;
        }
    }

    /**
     * Processes the xp drop and turns it into how much damage it did. Not entirely accurate due to fractional XP.
     * Rounds down so that in case it does get fractional it should not give false positives.
     *
     * @param skill Skill that xp was received in.
     * @param xp    Amount of XP that was received.
     */
    private void processXpDrop(Skill skill, int xp) {
        if (!validSkills.contains(skill)) {
            return;
        }

        Player player = Objects.requireNonNull(client.getLocalPlayer());
        Actor entity = player.getInteracting();
        if (!(entity instanceof NPC)) {
            return;
        }

        PlayerComposition playerComposition = player.getPlayerComposition();
        NPC npc = (NPC) entity;
        int id = npc.getId();

        if (Enemy.blacklist.contains(id)) {
            predictor.reset();
            // We actually always receive range xp, perhaps this can be used to
            // calculate the magic xp, as you seem to always receive .3 xp from swarms
            return;
        }

        Enemy enemy;
        if (activeEnemies.containsKey(npc.getIndex())) {
            enemy = activeEnemies.get(npc.getIndex());
        } else {
            Trace.damage("xp drop on untracked NPC {} (id={} idx={}) tick={}",
                    npc.getName(), npc.getId(), npc.getIndex(), client.getTickCount());
            predictor.reset();
            return;
        }

        int bossHealth = client.getVarbitValue(VarbitID.HPBAR_HUD_HP);
        if (bossHealth > 0 && Enemy.bosses.contains(npc.getId())) {
            Trace.damage("boss-health varbit re-sync: {} tick={} {} -> {}",
                    npc.getName(), client.getTickCount(), enemy.getCurrentHealth(), bossHealth);
            enemy.setCurrentHealth(bossHealth); // re-synchronize the health
        }

        int attackStyle = client.getVarpValue(VarPlayerID.COM_MODE);
        int weapon = playerComposition.getEquipmentId(KitType.WEAPON);

        boolean isDefensiveCast = attackStyle == 3;
        boolean isPoweredStaff = POWERED_STAVES.contains(weapon);
        boolean isChinchompa = CHINCHOMPAS.contains(weapon);
        boolean isScythe = SCYTHES.contains(weapon);
        double scaling = enemy.getModifier();
        Predictor.Properties props = new Predictor.Properties(skill,
                isDefensiveCast, isPoweredStaff,
                npc, scaling, enemy.getDamageMultiplier());

        if ((skill == Skill.RANGED || skill == Skill.MAGIC) && isDefensiveCast) {
            // Ignore in order to not double hit, insert the drop into
            // the tree in order to track the fraction
            Trace.damage("xp drop {} on {} tick={} (defensive cast, tracking only)",
                    xp, npc.getName(), client.getTickCount());
            predictor.insertInto(xp, props);
            return;
        }

        int damage;
        if (config.experimentalHitPrediction()) {
            damage = predictor.treePredict2(xp, props);
        } else {
            damage = predictor.treePredict(xp, props);
        }
        Trace.damage("xp drop {} -> predicted {} damage on {} tick={} (hp={}, queued={}, calibrated={})",
                xp, damage, npc.getName(), client.getTickCount(),
                enemy.currentHealth, enemy.getQueuedDamage(),
                predictor.isAccurate(skill));

        if (MULTI_HIT_WEAPONS.contains(weapon)) {
            // Reset on multihit weapons as we can't tell the exact hits
            // that build the hitsplat
            predictor.reset();
        }

        assert (damage >= 0);
        if (isChinchompa || isScythe) {
            // Multi-target weapons: total damage is split across nearby NPCs
            // by the per-target hitsplats themselves; we route through
            // handleAoe so death prediction fires only when the summed
            // damage wipes the whole clump. Individual targets are then
            // updated by HitsplatApplied → enemy.hit(amount) as usual.
            handleAoe(props, damage);
        } else {
            sendDamage(player, damage);
        }
    }

    private void handleAoe(Predictor.Properties properties, int damage) {
        NPC npc = properties.npc;
        List<Enemy> nearby = activeEnemies.values().stream()
                .filter(enemy -> npc.getWorldLocation().distanceTo(enemy.getNpc().getWorldLocation()) <= 1)
                .collect(Collectors.toList());

        if (nearby.stream().anyMatch(e -> npc.getId() != e.getNpc().getId())) {
            predictor.reset(); // can't determine how much each npc was damaged, reset instead
        }

        final int clumpHp = nearby.stream().mapToInt(Enemy::getCurrentHealth).sum();
        if (damage >= clumpHp) {
            sendClumpDamage(nearby);
        }
    }

    private void sendClumpDamage(List<Enemy> enemies) {
        for (Enemy enemy : enemies) {
            final int npcIndex = enemy.getNpc().getIndex();
            final EntityDamaged ev = new EntityDamaged(npcIndex, enemy.getCurrentHealth());
            if (party.isInParty()) {
                clientThread.invokeLater(() -> party.send(ev));
            }
            onEntityDamaged(ev);
        }
    }

    private void sendDamage(Player player, int damage) {
        if (damage <= 0) {
            return;
        }

        NPC npc = (NPC) player.getInteracting();

        final int npcIndex = npc.getIndex();
        final EntityDamaged entityDamaged = new EntityDamaged(npcIndex, damage);

        if (party.isInParty()) {
            clientThread.invokeLater(() -> party.send(entityDamaged));
        }
        onEntityDamaged(entityDamaged);
    }

    /**
     * Computes the difference between the updated xp drop and the previous one
     *
     * @param skill Skill XP was received in.
     * @param xp    Updated XP amount.
     */
    private void preProcessXpDrop(Skill skill, int xp) {
        int diff = xp - previousXps.getOrDefault(skill, 0);
        previousXps.put(skill, xp);
        processXpDrop(skill, diff);
    }

    /**
     * Queues damage on an entity. If the entity is a shadow, it hides the shadow.
     * If the entity is Akkha, it will highlight her.
     *
     * @param entityDamaged event
     */
    @Subscribe
    public void onEntityDamaged(EntityDamaged entityDamaged) {
        PartyMember localPlayer = party.getLocalMember();

        if (localPlayer != null) {
            if (localPlayer.getMemberId() == entityDamaged.getMemberId()) {
                return; // Don't process your own events
            }
        }

        Integer npcIndex = entityDamaged.getNpcIndex();
        Enemy enemy = activeEnemies.getOrDefault(npcIndex, null);
        if (enemy != null) {
            boolean died = enemy.queueDamage(entityDamaged.getDamage());
            if (died && enemy.isHideOnDeath()) {
                // npc.setDead is a RuneLite NPC API that requires the client thread.
                // onEntityDamaged can come from the party/WebSocket thread, so post
                // the side effect onto the client thread.
                NPC liveNpc = enemy.getNpc();
                if (liveNpc != null) {
                    clientThread.invoke(() -> liveNpc.setDead(true));
                }
            }
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged xpDrop) {
        preProcessXpDrop(xpDrop.getSkill(), xpDrop.getXp());
    }

    @Subscribe
    public void onFakeXpDrop(FakeXpDrop xpDrop) {
        //TODO hopefully this works. I don't have 200m in magic to find out.
        processXpDrop(xpDrop.getSkill(), xpDrop.getXp());
    }

    /**
     * Removes the hit from queued damage.
     *
     * @param hit hitsplat
     */
    @Subscribe
    public void onHitsplatApplied(HitsplatApplied hit) {
        Hitsplat hitsplat = hit.getHitsplat();
        if (hitsplat.getAmount() <= 0) {
            return;
        }

        Actor actor = hit.getActor();
        if (actor instanceof NPC) {
            NPC npc = (NPC) actor;
            Enemy enemy = activeEnemies.getOrDefault(npc.getIndex(), null);
            if (enemy == null) {
                Trace.damage("hitsplat on untracked NPC {} (id={} idx={}) tick={} amount={} type={} mine={} others={}",
                        npc.getName(), npc.getId(), npc.getIndex(),
                        client.getTickCount(), hitsplat.getAmount(), hitsplat.getHitsplatType(),
                        hitsplat.isMine(), hitsplat.isOthers());
                return;
            }

            int amount = hitsplat.getAmount();
            int type = hitsplat.getHitsplatType();
            int tick = client.getTickCount();
            int disappearsOn = hitsplat.getDisappearsOnGameCycle();
            boolean mine = hitsplat.isMine();
            boolean others = hitsplat.isOthers();

            switch (type) {
                case HitsplatID.HEAL:
                case HitsplatID.CYAN_UP:
                    // Seems that nightmare totems use this when healed
                case HitsplatID.DAMAGE_OTHER_WHITE:
                    enemy.heal(amount);
                    Trace.damage("HEAL {} on {}(idx={} id={}) tick={} type={} mine={} others={} fade={} (hp now {})",
                            amount, npc.getName(), npc.getIndex(), npc.getId(),
                            tick, type, mine, others, disappearsOn,
                            enemy.getCurrentHealth());
                    break;
                default:
                    enemy.hit(amount);
                    Trace.damage("HIT  {} on {}(idx={} id={}) tick={} type={} mine={} others={} fade={} (hp now {}, queued now {})",
                            amount, npc.getName(), npc.getIndex(), npc.getId(),
                            tick, type, mine, others, disappearsOn,
                            enemy.getCurrentHealth(), enemy.getQueuedDamage());
            }
        }
    }
}

